"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6530],{3366:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ActivePerksGuiController","desc":"Binds the Studio-authored `StarterGui.ActivePerksGui`: a read-only view of\\nthe perks buffing the player right now. Each tab lists the active permanent\\nperks first (`PerkClient`), then the run\'s shop perks: Personal = your\\n`ActiveRun.Personal` minus ended clocks; Party = every party shop perk live\\nin the run (`PartyPerkBuffs.<Id>HolderId ~= 0`). A Personal perk is active\\nat the player\'s own level > 0; a Party perk at the server-wide max, and\\n`PerkOwner` names the player holding it. Opens from a TopbarPlus icon\\n(toggle key O). It is the Game Instance\'s only perk GUI: perk changes are\\nLobby-only (`PerkMenuGuiController`).","realm":["Client"],"source":{"line":16,"path":"src/StarterPlayer/StarterPlayerScripts/ActivePerksGuiController.client.luau"}}')}}]);